int logfmt_parse_multi(const char *in, char **keys, char **vals, size_t max_pairs) {
    size_t num_pairs = 0;
    const char *pair_start = in;

    while (num_pairs < max_pairs) {
        const char *eq = strchr(pair_start, '=');
        if (!eq) break;
        size_t klen = (size_t)(eq - pair_start);
        keys[num_pairs] = malloc(klen + 1);
        if (!keys[num_pairs]) return -1;
        strncpy(keys[num_pairs], pair_start, klen);
        keys[num_pairs][klen] = '\0';

        const char *val_start = eq + 1;
        while (*val_start == ' ') val_start++;
        const char *val_end = strchr(val_start, ' ');
        if (!val_end) val_end = strchr(pair_start, '\0');

        size_t vlen = (size_t)(val_end - val_start);
        vals[num_pairs] = malloc(vlen + 1);
        if (!vals[num_pairs]) {
            for (size_t i = 0; i <= num_pairs; i++) free(keys[i]);
            return -1;
        }
        strncpy(vals[num_pairs], val_start, vlen);
        vals[num_pairs][vlen] = '\0';

        num_pairs++;
        pair_start = val_end + 1;
    }

    return num_pairs;
}

